const items = $input.all();
const output = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const meta = body.metadata || {};
  const data = body.data || {};

  // Determine if Credit or Sales payload using flow_type property
  const isCredit = body.flow_type === 'credit' || meta.flow_type === 'credit' || Boolean(data.risk_tier);

  output.push({
    json: {
      flow_type: isCredit ? 'credit' : 'sales',
      pipeline_type: isCredit ? 'Credit Operations' : 'Sales Operations',
      timestamp: meta.dispatch_timestamp || new Date().toISOString(),
      entity_name: data.business_name || data.company_name || 'N/A',
      contact_name: data.applicant_name || data.contact_person || 'N/A',
      industry: data.industry || 'General Commercial',
      financial_metric_usd: data.loan_amount_requested_usd || data.annual_revenue_usd || 0,
      assessment: data.risk_tier || `Score: ${data.lead_score}/100`,
      summary_notes: data.executive_summary || data.score_rationale || '',
      raw_payload: JSON.stringify(data)
    }
  });
}

return output;
